    about_hero_1: "SaaS control,",
    about_hero_2: "for everyone else.",
    about_hero_sub: "Enterprise-grade SaaS management, built for small and mid-sized European companies that can't justify €30,000 a year for software visibility.",
    about_problem_p1: "The average 100-person company now pays for more than 80 SaaS tools. Licences get forgotten. Employees leave and retain their access. Contracts auto-renew at inflated prices. For most organisations, nobody owns the full picture — and the cost of that ambiguity is material.",
    about_problem_p2: "The tools that solve this problem at enterprise scale — Zylo, Torii, Lumos — are excellent. They also charge between €30,000 and €50,000 per year and require dedicated procurement teams to operate. That leaves every company under 500 employees with two options: pay for chaos, or hire someone to chase it full-time.",
    about_approach_p1: "Stacklens is the third option. We deliver the core 80% of enterprise SaaS management — visibility, waste detection, renewal alerts, contract analysis — engineered specifically for small and mid-sized European organisations.",
    about_approach_p2: "Transparent pricing from €29 per month. Hosted in the EU. GDPR-native. No annual commitments. No sales calls. One clear mission: give every SMB the SaaS control that used to be reserved for the Fortune 500.",
    about_principle1_title: "Transparent pricing",
    about_principle1_body: "Public plans, no \"contact sales\" tier. You see the price before you sign up — including at enterprise level.",
    about_principle2_title: "European by design",
    about_principle2_body: "Hosted in the EU. GDPR-native from day one. Built for the regulatory and linguistic context of European SMBs.",
    about_principle3_title: "Focused scope",
    about_principle3_body: "We deliver the 80% of SaaS management that matters most. We do not try to be an HR suite, an IT ticketing system, or a SCIM/PAM platform.",
    about_principle4_title: "Accessible support",
    about_principle4_body: "Direct communication with the team that builds the product. No tier-one queues, no 48-hour SLAs.",
    about_cta_sub: "Free plan includes up to 10 tools and 25 employees. No credit card required.",
