    lp_feat_dedicated_support: "Dedicated support",
    lp_pricing_footnote: "Free plan available now. Paid plans include EU data hosting, GDPR compliance, and unlimited contract analyses.",
    lp_faq_q1: "How is this different from Zylo, Torii, or Lumos?",
    lp_faq_a1: "Those are excellent products built for enterprises with €30-50K budgets and dedicated procurement teams. Stacklens does the core 80% — visibility, waste detection, renewal alerts — at 1/20th the price. We do not do SCIM or PAM. If you need those, talk to them. If you just need to see what you are paying for, talk to us.",
    lp_faq_q2: "Where is my data stored?",
    lp_faq_a2: "Google Cloud, europe-west1 (Belgium). Your data never leaves the EU. Each customer gets isolated Firestore databases — no shared infrastructure. GDPR-native, not GDPR-bolted-on.",
    lp_faq_q3: "Do I need to give you admin access to my Google Workspace?",
    lp_faq_q4: "Do I need a credit card to try it?",
    lp_faq_a4: "No. The free tier requires no credit card and lasts forever for small teams. Paid tiers offer 7-day trials with no credit card upfront.",
    lp_faq_q5: "How long does setup take?",
    lp_faq_a5: "About 5 minutes. Sign up, upload a CSV (or add a few tools manually), invite your team. Most customers see their first savings opportunity within 10 minutes.",
    lp_faq_q6: "What if I want to cancel?",
    lp_faq_a6: "Click \"Cancel subscription\" in Settings. No retention emails. No \"are you sure?\" dialogs. Your data stays accessible for 30 days, then is deleted.",
    lp_final_subtitle: "Free forever for up to 10 tools. No credit card. No demo call. Just sign up and start.",
    lp_final_cta: "Create my free account",
    lp_final_note: "7-day trial of Pro features included. Downgrade anytime.",
