    lp_hero_badge: "🇪🇺 EU-hosted · GDPR-native · Built for European SMBs",
    lp_hero_h1_line1: "Stop SaaS drift",
    lp_hero_h1_line2: "before it costs you.",
    lp_hero_body: "You're the one person chasing invoices, renewals, and zombie accounts across 80+ tools. Stacklens gives you the visibility to find what's wasted, who still has access, and what's about to auto-renew — in 5 minutes, not 5 days.",
