    lp_find_hiding: "Find what's hiding in your stack →",
    lp_who_body: "You didn't sign up to manage 80+ SaaS tools. But someone has to chase the renewals, clean up the zombie accounts, and answer \"how much are we spending on software?\" — and that someone is you.",
    lp_persona1_role: "IT Manager",
    lp_persona1_pain: "Tracking access across 80+ tools with a spreadsheet that was last updated 3 months ago.",
    lp_persona2_role: "Finance / Ops",
    lp_persona2_pain: "Chasing invoices from 40 different vendors with no central view of what you're actually paying.",
    lp_persona3_role: "Founder / CEO",
    lp_persona3_pain: "Knowing you're overspending on SaaS but having no idea where the waste is.",
    lp_pricing_badge_popular: "Most popular",
    lp_pricing_fine_print: "Free plan available now. Paid plans include EU data hosting, GDPR compliance, and unlimited contract analyses.",
    lp_pricing_local_note: "Prices shown in {code} based on your location and billed in your local currency at checkout. Exchange rates are indicative.",
    lp_faq2_q: "How is this different from Zylo, Torii, or Lumos?",
    lp_faq2_a: "Those are excellent products built for enterprises with €30-50K budgets and dedicated procurement teams. Stacklens does the core 80% — visibility, waste detection, renewal alerts — at 1/20th the price. We do not do SCIM or PAM. If you need those, talk to them. If you just need to see what you are paying for, talk to us.",
    lp_faq3_q: "Where is my data stored?",
    lp_faq3_a: "Your records are stored on Google Cloud in the EU, isolated per customer — no shared infrastructure. Some processing (AI features and payments) runs on Google and Stripe systems that may be outside the EU. GDPR-native, not GDPR-bolted-on.",
    lp_faq4_q: "Do I need to give you admin access to my Google Workspace?",
    lp_faq4_a: "No. CSV import works for everything. OAuth-based directory sync is available now for Google Workspace, Microsoft 365, and Okta — or paste a list of tools manually or upload a CSV from your accounting system.",
    lp_faq5_q: "Do I need a credit card to try it?",
    lp_faq5_a: "No. The free tier requires no credit card and lasts forever for small teams. Paid tiers offer 7-day trials with no credit card upfront.",
    lp_faq6_q: "How long does setup take?",
    lp_faq6_a: "About 5 minutes. Sign up, upload a CSV (or add a few tools manually), invite your team. Most customers see their first savings opportunity within 10 minutes.",
    lp_faq7_q: "What if I want to cancel?",
    lp_faq7_a: "Click \"Cancel subscription\" in Settings. No retention emails. No \"are you sure?\" dialogs. Your data stays accessible for 30 days, then is deleted.",
    lp_faq8_q: "Who's behind Stacklens?",
    lp_faq8_a: "Stacklens is an independent European software company. We're small and product-focused — which means you deal directly with the people who build the product, not a call centre. Payments are handled by Stripe, hosting by Google Cloud, and your data is yours to export or delete at any time. Full company and contact details are on our Legal page.",
    lp_final_cta_body: "Free forever for up to 10 tools. No credit card. No demo call. Just sign up and start.",
    lp_final_cta_btn: "Create my free account",
    lp_final_cta_note: "7-day trial of Pro features included. Downgrade anytime.",
