    lp_p3_action: "Définir un rappel →",
    lp_p4_title: "Shadow IT : 14 employés utilisent ChatGPT Plus",
    lp_p4_sub: "Outil non approuvé adopté par l'ingénierie — pas de revue sécurité",
    lp_p4_action: "Revoir l'outil →",
    lp_p5_title: "GitHub n'impose pas le MFA",
    lp_p5_sub: "Outil à haut risque avec accès au code source — MFA non requis",
    lp_p5_action: "Activer le MFA →",
    lp_p6_title: "Figma n'a pas de propriétaire assigné",
    lp_p6_sub: "Personne n'est responsable de cet outil à 480€/mois",
    lp_p6_action: "Assigner un propriétaire →",
    lp_find_hiding: "Découvrez ce qui se cache dans votre pile →",
    lp_who_body: "Vous ne vous êtes pas inscrit pour gérer 80+ outils SaaS. Mais quelqu'un doit chasser les renouvellements, nettoyer les comptes zombies et répondre à \"combien dépensons-nous en logiciels ?\" — et cette personne, c'est vous.",
    lp_persona1_role: "Responsable IT",
    lp_persona1_pain: "Suivre les accès sur 80+ outils avec un tableur mis à jour pour la dernière fois il y a 3 mois.",
    lp_persona2_role: "Finance / Ops",
    lp_persona2_pain: "Chasser les factures de 40 fournisseurs différents sans vue centralisée de ce que vous payez vraiment.",
    lp_persona3_role: "Fondateur / CEO",
    lp_persona3_pain: "Savoir que vous dépensez trop en SaaS mais ne pas savoir où se trouve le gaspillage.",
    lp_pricing_badge_popular: "Le plus populaire",
    lp_pricing_fine_print: "Plan gratuit disponible maintenant. Les plans payants incluent l'hébergement UE, la conformité RGPD et des analyses de contrats illimitées.",
    lp_pricing_local_note: "Prix affichés en {code} selon votre localisation et facturés dans votre devise locale au paiement. Les taux de change sont indicatifs.",
    lp_faq2_q: "En quoi est-ce différent de Zylo, Torii ou Lumos ?",
    lp_faq2_a: "Ce sont d'excellents produits conçus pour les grandes entreprises avec des budgets de 30-50K€ et des équipes dédiées aux achats. Stacklens fait les 80% essentiels — visibilité, détection du gaspillage, alertes de renouvellement — à 1/20ème du prix.",
    lp_faq3_q: "Où sont stockées mes données ?",
    lp_faq3_a: "Vos données sont stockées sur Google Cloud dans l'UE, isolées par client — pas d'infrastructure partagée. Certains traitements (fonctions IA et paiements) s'exécutent sur des systèmes Google et Stripe pouvant se situer hors de l'UE. RGPD natif, pas RGPD en option.",
    lp_faq4_q: "Dois-je vous donner un accès administrateur à mon Google Workspace ?",
    lp_faq4_a: "Não. A importação de CSV funciona para tudo. A sincronização de diretório via OAuth já está disponível para Google Workspace, Microsoft 365 e Okta — ou cole manualmente uma lista de ferramentas ou envie um CSV do seu sistema de contabilidade.",
    lp_faq5_q: "Ai-je besoin d'une carte bancaire pour essayer ?",
    lp_faq5_a: "Non. Le plan gratuit ne nécessite pas de CB et dure pour toujours pour les petites équipes. Les plans payants offrent des essais de 7 jours sans CB.",
    lp_faq6_q: "Combien de temps dure la configuration ?",
    lp_faq6_a: "Environ 5 minutes. Inscrivez-vous, importez un CSV (ou ajoutez quelques outils manuellement), invitez votre équipe. La plupart des clients voient leur première opportunité d'économie en 10 minutes.",
    lp_faq7_q: "Et si je veux annuler ?",
    lp_faq7_a: "Cliquez sur \"Annuler l'abonnement\" dans les Paramètres. Pas d'emails de rétention. Pas de dialogues \"êtes-vous sûr ?\". Vos données restent accessibles 30 jours, puis sont supprimées.",
    lp_faq8_q: "Qui est derrière Stacklens ?",
    lp_faq8_a: "Stacklens est une société de logiciels européenne indépendante. Nous sommes une petite équipe centrée sur le produit — vous échangez donc directement avec les personnes qui le construisent, pas un centre d'appels. Les paiements sont gérés par Stripe, l'hébergement par Google Cloud, et vos données vous appartiennent : exportez-les ou supprimez-les à tout moment. Les mentions légales complètes figurent sur notre page Légal.",
    lp_final_cta_body: "Gratuit pour toujours jusqu'à 10 outils. Sans CB. Sans appel de démonstration. Inscrivez-vous et commencez.",
    lp_final_cta_btn: "Créer mon compte gratuit",
    lp_final_cta_note: "7 jours d'essai des fonctionnalités Pro inclus. Rétrogradez à tout moment.",
